# and still reports success); "-" is its sold-out mark (qty 0, not on sale)
MIN_MARKET_QTY = 2
SOLD_OUT = "-"


def market_qty(product, settings):
    """Units we offer on the market: free stock minus the CS safety units."""
    return max(product.available - settings.market_safety_stock, 0)


def shown_qty(qty):
    """What the market ends up showing for a quantity once the feed encodes it."""
    return qty if qty >= MIN_MARKET_QTY else 0


def feed_line(sku, qty):
    qty = int(qty)
    return f"{sku}\t{qty if qty >= MIN_MARKET_QTY else SOLD_OUT}"

